def sort_patients(patient_info)
    elderly, non_elderly = patient_info.partition { |_, age| age >= 60 }
    sorted_elderly = elderly.sort_by { |_, age| -age }
    sorted_elderly + non_elderly
  end


def count_prime_pairs(even_number)
    # Helper function to check if a number is prime
    def is_prime?(num)
      return false if num <= 1
      (2...num).none? { |i| num % i == 0 }
    end

    # Generating a list of primes up to even_number
    primes = (2...even_number).select { |num| is_prime?(num) }

    # Counting distinct prime pairs
    count = 0
    primes.each_with_index do |prime, index|
      count += 1 if primes[index..-1].any? { |other_prime| prime + other_prime == even_number }
    end

    count
  end

def generate_four_digit_permutations(*digits)
    permutations = digits.permutation(4).to_a
    permutations.map! { |perm| perm.join }
    permutations.sort
  end

def sort_dates(dates)
    dates.sort_by { |date| date.split('/').rotate(-1).join }
  end

def count_chars_in_title(title)
    title.count("^ \n")
  end
